    if (w == NULL) return true;
    w->addWifiListener(&sWifi);
    w->startScan();
    std::vector<WifiInfo> infos;
    w->getWifiScanInfosLock(infos);                  // 也可等回调
    LOGD("n=%d ip=%s\n", (int) infos.size(), w->getIp());
    return true;
}
